entries
        .flatten()
        .filter(|entry| {
            let path = entry.path();
            let is_session = path.extension().map(|ext| ext == "jsonl").unwrap_or(false);
            if !is_session {
                return false;
            }
            entry
                .metadata()
                .ok()
                .and_then(|m| m.modified().ok())
                .map(|mtime| mtime > since_time)
                .unwrap_or(false)
        }).count

memories
