        .map(|mem| {
            let tag = match mem.memory_type {
                Some(ref mt) => format!("[{}] ", mt),
                None => String::new(),
            };
            let ts = format_timestamp_iso(mem.mtime_ms);
            match &mem.description {
                Some(desc) => format!("- {}{} ({}): {}", tag, mem.filename, ts, desc),
                None => format!("- {}{} ({})", tag, mem.filename, ts),
            }
        })
        .collect::<Vec<_>>().join

